package org.securemail.worker;

import com.sun.net.httpserver.HttpServer;
import org.junit.jupiter.api.Test;
import org.securemail.community.agent.AgentJson;
import org.securemail.community.protocol.CommunityAuth;
import java.io.*;
import java.net.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import static org.junit.jupiter.api.Assertions.*;

/** Real signed HTTP fixture over a deliberately injected loopback connector; Tor acceptance is separate. */
final class WorkerCoordinatorClientTest {
 static final URI ONION=URI.create("http://"+"a".repeat(56)+".onion");
 @Test void requestAndExactResponseAreAuthenticated()throws Exception{KeyPair serverKey=KeyPairGenerator.getInstance("Ed25519").generateKeyPair(),worker=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),2);AtomicBoolean requestValid=new AtomicBoolean();server.createContext("/api/v1",x->{try{byte[] body=x.getRequestBody().readAllBytes();String nonce=x.getRequestHeaders().getFirst("AEGIS-Nonce");long time=Long.parseLong(x.getRequestHeaders().getFirst("AEGIS-Time"));requestValid.set(CommunityAuth.verify(worker.getPublic().getEncoded(),CommunityAuth.requestBytes(CommunityAuth.id(serverKey.getPublic().getEncoded()),time,nonce,body),Base64.getDecoder().decode(x.getRequestHeaders().getFirst("AEGIS-Signature"))));byte[] response=AgentJson.bytes(Map.of("ok",true,"data",Map.of("job",Map.of()),"authorizationEpoch",1,"serverTime",System.currentTimeMillis(),"requestIdentity",CommunityAuth.id(worker.getPublic().getEncoded()),"requestSha256",CommunityAuth.id(CommunityAuth.requestBytes(CommunityAuth.id(serverKey.getPublic().getEncoded()),time,nonce,body))));x.getResponseHeaders().set("AEGIS-Signature",Base64.getEncoder().encodeToString(CommunityAuth.sign(serverKey.getPrivate(),CommunityAuth.responseBytes(CommunityAuth.id(serverKey.getPublic().getEncoded()),nonce,response))));x.sendResponseHeaders(200,response.length);x.getResponseBody().write(response);x.close();}catch(Exception e){throw new IOException(e);}});server.start();try{var client=new WorkerCoordinatorClient(ONION,serverKey.getPublic().getEncoded(),worker,(host,port)->{assertEquals(ONION.getHost(),host);return new Socket("127.0.0.1",server.getAddress().getPort());});assertEquals(Map.of(),client.call("agent.worker.claim",Map.of()).get("job"));assertTrue(requestValid.get());assertThrows(IOException.class,()->client.call("admin.role.create",Map.of()));}finally{server.stop(0);}}
 @Test void unsignedTamperedOrWrongIdentityResponseIsRejected()throws Exception{var serverKey=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();var worker=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),2);server.createContext("/api/v1",x->{x.getRequestBody().readAllBytes();byte[] response=AgentJson.bytes(Map.of("ok",true,"data",Map.of("job",Map.of())));x.getResponseHeaders().set("AEGIS-Signature",Base64.getEncoder().encodeToString(new byte[64]));x.sendResponseHeaders(200,response.length);x.getResponseBody().write(response);x.close();});server.start();try{var client=new WorkerCoordinatorClient(ONION,serverKey.getPublic().getEncoded(),worker,(host,port)->new Socket("127.0.0.1",server.getAddress().getPort()));assertThrows(IOException.class,()->client.call("agent.worker.claim",Map.of()));}finally{server.stop(0);}}
 @Test void coordinatorCannotBeSilentlyChangedToClearnetOrLocalhost()throws Exception{var key=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();for(String address:List.of("https://example.com/","http://127.0.0.1/","http://example.com/","http://"+"a".repeat(56)+".onion:81/"))assertThrows(IOException.class,()->new WorkerCoordinatorClient(URI.create(address),key.getPublic().getEncoded(),key,9050));}
 @Test void unavailableTorNeverFallsBackToDirectNetwork()throws Exception{var key=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();int unused;try(ServerSocket reserved=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"))){unused=reserved.getLocalPort();}var client=new WorkerCoordinatorClient(ONION,key.getPublic().getEncoded(),key,unused);assertThrows(IOException.class,()->client.call("agent.worker.claim",Map.of()));}
 @Test void validServerSignatureForDifferentRequestOrActorCannotBeSubstituted()throws Exception{for(boolean wrongActor:List.of(true,false)){KeyPair serverKey=KeyPairGenerator.getInstance("Ed25519").generateKeyPair(),worker=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),2);server.createContext("/api/v1",x->{try{byte[]body=x.getRequestBody().readAllBytes();String nonce=x.getRequestHeaders().getFirst("AEGIS-Nonce");long time=Long.parseLong(x.getRequestHeaders().getFirst("AEGIS-Time"));String audience=CommunityAuth.id(serverKey.getPublic().getEncoded());byte[]response=AgentJson.bytes(Map.of("ok",true,"data",Map.of("job",Map.of()),"requestIdentity",wrongActor?"f".repeat(64):CommunityAuth.id(worker.getPublic().getEncoded()),"requestSha256",wrongActor?CommunityAuth.id(CommunityAuth.requestBytes(audience,time,nonce,body)):"f".repeat(64)));x.getResponseHeaders().set("AEGIS-Signature",Base64.getEncoder().encodeToString(CommunityAuth.sign(serverKey.getPrivate(),CommunityAuth.responseBytes(audience,nonce,response))));x.sendResponseHeaders(200,response.length);x.getResponseBody().write(response);x.close();}catch(Exception e){throw new IOException(e);}});server.start();try{var client=new WorkerCoordinatorClient(ONION,serverKey.getPublic().getEncoded(),worker,(host,port)->new Socket("127.0.0.1",server.getAddress().getPort()));assertThrows(IOException.class,()->client.call("agent.worker.claim",Map.of()));}finally{server.stop(0);}}}
 @Test void absoluteDeadlineClosesAStalledCoordinatorSocket()throws Exception{var key=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();try(ServerSocket listener=new ServerSocket(0,1,InetAddress.getByName("127.0.0.1"))){Thread responder=new Thread(()->{try(Socket socket=listener.accept()){socket.getInputStream().read();Thread.sleep(500);}catch(Exception ignored){}},"stall-fixture");responder.start();var client=new WorkerCoordinatorClient(ONION,key.getPublic().getEncoded(),key,(host,port)->new Socket("127.0.0.1",listener.getLocalPort()),100);long started=System.nanoTime();assertThrows(IOException.class,()->client.call("agent.worker.claim",Map.of()));assertTrue(System.nanoTime()-started<1000000000L);responder.join(2000);}}

}
